import React, { useState,useEffect } from "react";



const AuthContext = React.createContext({
  isLoggedIn: false,
  onLogout: () => {},
  onLogin:(email,password,college)=>{},
});

export const AuthContextProvider = (props) => {

  const [isLoggedIn, setIsLoggedIn] = useState(false);
     
  useEffect(()=>{
    const stordUserDetails=localStorage.getItem('isLoggedIn');    
    if(stordUserDetails==='1'){
     setIsLoggedIn(true);
    }
  },[]);

  const logoutHandler = () => {
    localStorage.removeItem('isLoggedIn');
    setIsLoggedIn(false);
  };
  // const loginHandler = (email,password,college) => {
    
  //   localStorage.setItem('isLoggedIn','1');
  //      setIsLoggedIn(true);

  //      console.log('Attempting login...');
  //      const loginSuccessful = true;

  //      if (loginSuccessful) {
  //        console.log('Login successful!');
  //        localStorage.setItem('isLoggedIn', '1');
  //        setIsLoggedIn(true);
  //      } else {
  //        console.log('Login failed. Check your credentials.');
  //      }
  
  // };  
  const loginHandler = async (email, password, college) => {
    try {
      console.log('Attempting login...');
    
      // Your login logic here
          localStorage.setItem('isLoggedIn','1');
       setIsLoggedIn(true);
      // For simplicity, let's assume a successful login for any email and password
      const loginSuccessful = true;
  
      if (loginSuccessful) {
        console.log('Login successful!');
        localStorage.setItem('isLoggedIn', '1');
        setIsLoggedIn(true);
      } else {
        console.log('Login failed. Check your credentials.');
      }
    } catch (error) {
      console.error('Error during login:', error);
    }
  };
  return (
    <AuthContext.Provider
      value={{
        isLoggedIn: isLoggedIn,
        onLogout: logoutHandler,
        onLogin: loginHandler,
      }}
    >
      {props.children}
    </AuthContext.Provider>
  );
};

export default AuthContext;
